Item.method_code:
const serverMethod = aras.newIOMItem(inDom.getAttribute('type'), 'GetItemAccessReportData');
serverMethod.setID(inDom.getAttribute('id'));
const reportData = serverMethod.apply();

let report = aras.newIOMItem('Report', 'get');
report.setAttribute('select', 'xsl_stylesheet');
report.setProperty('name', 'Item Access Report');
report = report.apply();

let result;
let xslStylesheet = report.getProperty('xsl_stylesheet');
if (xslStylesheet) {
	const xsltStylesheetDOM = aras.createXMLDocument();
	xsltStylesheetDOM.loadXML(xslStylesheet);

	xslStylesheet = xsltStylesheetDOM.xml;

	const res = aras.createXMLDocument();
	res.loadXML(reportData.dom.xml);

	result = aras.applyXsltString(res, xslStylesheet);
}

return result;
